/* An encrypted, short-lived transfer; private data never ships with the app. */
(function(root){
'use strict';
function bytes(s){if(typeof s!=='string'||!/^[A-Za-z0-9_-]+$/.test(s))throw Error('Association invalide.');return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),function(c){return c.charCodeAt(0);});}
async function open(packet,code){if(!packet||packet.format!=='hub-connections'||packet.version!==1||typeof code!=='string'||code.length!==43||typeof packet.data!=='string'||packet.data.length>18000000)throw Error('Association invalide.');try{var key=await crypto.subtle.importKey('raw',bytes(code),'AES-GCM',false,['decrypt']),data=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(packet.iv),additionalData:new TextEncoder().encode('hub-connections-v1')},key,bytes(packet.data));var value=JSON.parse(new TextDecoder().decode(data));}catch(_){throw Error('Code incorrect ou fichier modifié.');}if(!Number.isFinite(value.expires)||value.expires<Date.now()||value.expires>Date.now()+31*60000)throw Error('Association expirée.');if(!Array.isArray(value.calendars)||value.calendars.length>30)throw Error('Association invalide.');if(value.homeAssistant){try{value.homeAssistant=root.HubHA.credentials(value.homeAssistant);}catch(_){throw Error('Connexion Home Assistant invalide.');}}return value;}
root.HubConnectionBundle={open:open};
}(typeof window==='undefined'?globalThis:window));
